    'body_html' => '<section class="wgba-section" id="problem"><h2>সমস্যাটা কী?</h2><p>জালিয়াতি-অর্ডার শনাক্তকারী মডেলের রিপোর্ট: “accuracy ৯৮%”। কিন্তু মাস শেষে দেখা গেল ২০টি জালিয়াতির ১৮টিই ধরা পড়েনি। ৯৮% কীভাবে সম্ভব হলো?</p></section>
<section class="wgba-section" id="objectives"><h2>শেখার লক্ষ্য</h2><ul><li>confusion matrix থেকে accuracy, precision, recall ও F1 হিসাব করতে পারবেন</li><li>imbalanced ডেটায় accuracy কেন বিভ্রান্তিকর তা উদাহরণসহ দেখাতে পারবেন</li><li>কাজের প্রয়োজন অনুযায়ী precision বা recall-কে অগ্রাধিকার দেওয়ার যুক্তি দিতে পারবেন</li></ul><p class="wgba-meta">আনুমানিক সময়: 40 মিনিট</p></section>
<section class="wgba-section" id="prereq"><h2>পূর্বশর্ত</h2><ul><li><a href="/ai-academy/lesson/overfitting-regularization/">Underfitting, Overfitting ও Regularization</a></li></ul></section>
<section class="wgba-section" id="explain"><h2>ব্যাখ্যা</h2><div class="wgba-table-wrap"><table><caption>confusion matrix</caption><thead><tr><th scope="col"></th><th scope="col">আসলে positive (অভিযোগ)</th><th scope="col">আসলে negative</th></tr></thead><tbody><tr><td>মডেল বলল positive</td><td>TP (সঠিক ধরা)</td><td>FP (ভুল অ্যালার্ম)</td></tr><tr><td>মডেল বলল negative</td><td>FN (মিস)</td><td>TN (সঠিক ছাড়)</td></tr></tbody></table></div><div class="wgba-table-wrap"><table><caption>চার metric</caption><thead><tr><th scope="col">Metric</th><th scope="col">সূত্র</th><th scope="col">প্রশ্ন</th></tr></thead><tbody><tr><td>Accuracy</td><td>(TP + TN) / সব</td><td>মোট কত শতাংশ ঠিক?</td></tr><tr><td>Precision</td><td>TP / (TP + FP)</td><td>“positive” বললে কতবার সত্যি?</td></tr><tr><td>Recall</td><td>TP / (TP + FN)</td><td>আসল positive-এর কতগুলো ধরলাম?</td></tr><tr><td>F1</td><td>২ × P × R / (P + R)</td><td>precision ও recall-এর ভারসাম্য</td></tr></tbody></table></div><p><strong>সমস্যার উত্তর:</strong> ১০০০ অর্ডারে ২০টি জালিয়াতি। মডেল ২টি ধরেছে (TP = ২), ১৮টি মিস (FN = ১৮), ভুল অ্যালার্ম ২ (FP = ২), বাকি ৯৭৮ TN। Accuracy = (২ + ৯৭৮)/১০০০ = ৯৮%। কিন্তু recall = ২/২০ = ১০%!</p><p><strong>Trade-off:</strong> threshold কমালে বেশি positive বলা হয় → recall বাড়ে, precision সাধারণত কমে। কোনটি গুরুত্বপূর্ণ তা কাজ ঠিক করে: জালিয়াতিতে recall (মিস ব্যয়বহুল), স্প্যাম ফিল্টারে precision (আসল মেইল হারানো ব্যয়বহুল)।</p><div class="wgba-note wgba-note-warn"><strong>Edge case:</strong> মডেল কখনো positive না বললে TP + FP = ০, precision-এর হর শূন্য। কিছু লাইব্রেরি ০ ধরে, কিছু সতর্কবার্তা দেয়। রিপোর্টে স্পষ্ট লিখুন “অসংজ্ঞায়িত—কোনো positive অনুমান নেই”।</div></section>
<section class="wgba-section" id="analogy"><h2>উপমা — এবং কোথায় ভাঙে</h2><p><strong>উপমা:</strong> Precision হলো জেলের জালে যা উঠল তার কতটা মাছ (বাকি আবর্জনা); recall হলো পুকুরের সব মাছের কতটা জালে উঠল।</p><p><strong>কোথায় ভাঙে:</strong> জেল পুকুরে কত মাছ আছে আন্দাজ করতে পারেন; বাস্তব সিস্টেমে মিস হওয়া positive (FN) প্রায়ই অজানা থাকে—কেউ সেগুলো লেবেল না করলে recall মাপাই যায় না।</p></section>
<section class="wgba-section" id="worked"><h2>ধাপে ধাপে উদাহরণ</h2><p>১০টি মেসেজ: আসল [১,১,১,০,০,০,০,০,০,০], অনুমান [১,০,১,১,০,০,০,০,০,০]।</p><ol><li>TP = ২ (১ম, ৩য়), FN = ১ (২য়), FP = ১ (৪র্থ), TN = ৬।</li><li>Accuracy = ৮/১০ = ০.৮।</li><li>Precision = ২/৩ ≈ ০.৬৬৭; Recall = ২/৩ ≈ ০.৬৬৭।</li><li>F1 = ২ × ০.৬৬৭ × ০.৬৬৭ / (১.৩৩৩) ≈ ০.৬৬৭।</li><li>“সব ০” মডেল: accuracy ০.৭, precision অসংজ্ঞায়িত, recall ০।</li></ol></section>
<section class="wgba-section" id="activity"><h2>অনুশীলন / অ্যাক্টিভিটি</h2><div class="wgba-note">কোডে metric ফাংশন, worked উদাহরণ যাচাই, তারপর একটি স্কোর-তালিকায় threshold সরিয়ে precision-recall টেবিল।</div><h3>confusion matrix, metric ও threshold sweep</h3><div class="wgba-playground-slot" data-exercise="ex-les-04-06-metrics-1"><pre class="wgba-code"><code>function confusion(actual, pred) {
  const c = { TP: 0, FP: 0, FN: 0, TN: 0 };
  actual.forEach((a, i) =&gt; {
    const p = pred[i];
    if (a === 1 &amp;&amp; p === 1) c.TP++;
    else if (a === 0 &amp;&amp; p === 1) c.FP++;
    else if (a === 1 &amp;&amp; p === 0) c.FN++;
    else c.TN++;
  });
  return c;
}
const safeDiv = (a, b) =&gt; (b === 0 ? null : a / b);
function metrics(c) {
  const precision = safeDiv(c.TP, c.TP + c.FP);
  const recall = safeDiv(c.TP, c.TP + c.FN);
  const f1 = precision === null || recall === null || precision + recall === 0 ? null : (2 * precision * recall) / (precision + recall);
  return { accuracy: (c.TP + c.TN) / (c.TP + c.FP + c.FN + c.TN), precision, recall, f1 };
}
const r3 = (x) =&gt; (x === null ? &quot;অসংজ্ঞায়িত&quot; : Math.round(x * 1000) / 1000);
