    'body_html' => '<section class="wgba-section" id="problem"><h2>সমস্যাটা কী?</h2><p>অধ্যায় ২-এর অ্যাসিস্ট্যান্ট “পার্সেল কবে আসবে” বুঝতে পারেনি কারণ কেউ “পার্সেল” কীওয়ার্ড লেখেনি। নিয়ম হাতে না লিখে লেবেল-করা উদাহরণ থেকে শব্দের weight শিখলে কি ভালো হবে? আর কীভাবে জানব “ভালো” মানে আসলে কতটা ভালো?</p></section>
<section class="wgba-section" id="objectives"><h2>শেখার লক্ষ্য</h2><ul><li>টেক্সট থেকে bag-of-words feature vector বানাতে পারবেন</li><li>softmax ও বহু-বিভাগ cross-entropy দিয়ে classifier train করতে পারবেন</li><li>held-out test-এ per-class metric ও ভুলের বিশ্লেষণ রিপোর্ট করতে এবং ফলের সীমা লিখতে পারবেন</li></ul><p class="wgba-meta">আনুমানিক সময়: 70 মিনিট</p></section>
<section class="wgba-section" id="prereq"><h2>পূর্বশর্ত</h2><ul><li><a href="/ai-academy/lesson/data-leakage/">Data Leakage ও বিভ্রান্তিকর মূল্যায়ন</a></li><li><a href="/ai-academy/lesson/project-support-assistant/">প্রজেক্ট: Rule-based Support Assistant</a></li></ul></section>
<section class="wgba-section" id="explain"><h2>ব্যাখ্যা</h2><p><strong>ব্যাগ-অফ-ওয়ার্ডস</strong> (<em lang="en">bag-of-words</em>): একটি শব্দভাণ্ডার (vocabulary) বানাই; প্রতিটি মেসেজ একটি vector যেখানে i-তম সংখ্যা = শব্দভাণ্ডারের i-তম শব্দ মেসেজে কতবার আছে। শব্দের ক্রম হারিয়ে যায়—“ফেরত চাই না” ও “না, ফেরত চাই” একই vector।</p><p><strong>সফটম্যাক্স</strong> (<em lang="en">softmax</em>): K বিভাগের স্কোর zₖ থেকে সম্ভাব্যতা: pₖ = e^(zₖ) / Σⱼ e^(zⱼ)। সব pₖ > ০ এবং যোগ = ১ (অধ্যায় ৩-এর distribution)। <strong>সংখ্যাগত স্থিতিশীলতা:</strong> e^(১০০০) overflow করে, তাই আগে সব z থেকে সর্বোচ্চটি বাদ দিই—ফল গাণিতিকভাবে একই।</p><p><strong>Softmax regression:</strong> প্রতিটি বিভাগের নিজস্ব weight vector; z = Wx + b। Loss = −log(সঠিক বিভাগের p)। Gradient: ∂L/∂zₖ = pₖ − yₖ (y one-hot)—logistic-এর (p − y)-এর সাধারণ রূপ।</p><div class="wgba-note wgba-note-warn"><strong>সৎ সীমা:</strong> ৩৬টি মেসেজ আমরা নিজেরা লিখেছি, তাই শব্দচয়ন আমাদের মতো। test-এ যত ভালো ফলই আসুক, তা শুধু “এই সিন্থেটিক বিতরণে” প্রযোজ্য। বাস্তব গ্রাহকের বানান, বাংলিশ, লম্বা বাক্য, নতুন বিষয়—এসবে আলাদাভাবে মূল্যায়ন ছাড়া কোনো দাবি করা যাবে না।</div></section>
<section class="wgba-section" id="analogy"><h2>উপমা — এবং কোথায় ভাঙে</h2><p><strong>উপমা:</strong> bag-of-words হলো মেসেজকে শব্দের ঝুড়িতে ঢেলে গুনে দেখা; softmax regression শেখে কোন শব্দ কোন ঝুড়ি-বিভাগের দিকে কতটা ভোট দেয়।</p><p><strong>কোথায় ভাঙে:</strong> মানুষ বাক্যের ক্রম ও “না”-এর অর্থ বোঝে; ঝুড়িতে ঢাললে ক্রম হারিয়ে যায়। আর মডেল শুধু training-এ দেখা শব্দেরই weight জানে—নতুন শব্দ তার কাছে অদৃশ্য।</p></section>
<section class="wgba-section" id="worked"><h2>ধাপে ধাপে উদাহরণ</h2><p>শব্দভাণ্ডার: [ডেলিভারি, ফেরত, কোথায়]; মেসেজ “ডেলিভারি কোথায়” → x = [১, ০, ১]।</p><ol><li>ধরি z = [shipping ১.২, returns −০.৫, status ১.৮]।</li><li>স্থিতিশীলতার জন্য সর্বোচ্চ ১.৮ বাদ: [−০.৬, −২.৩, ০]।</li><li>e^: [০.৫৪৯, ০.১০০, ১.০০০]; যোগ = ১.৬৪৯।</li><li>p ≈ [০.৩৩৩, ০.০৬১, ০.৬০৬] → অনুমান status।</li><li>আসল status হলে loss = −log ০.৬০৬ ≈ ০.৫০১; gradient ∂L/∂z = [০.৩৩৩, ০.০৬১, −০.৩৯৪]।</li></ol></section>
<section class="wgba-section" id="activity"><h2>অনুশীলন / অ্যাক্টিভিটি</h2><p><strong>প্রজেক্ট মানদণ্ড:</strong> (১) test সেটে per-class precision/recall টেবিল, (২) প্রতিটি ভুল শ্রেণিবিভাগের মেসেজ ও কারণ, (৩) অধ্যায় ২-এর ব্যর্থ মেসেজে মডেলের আচরণ, (৪) “এই ফল কী প্রমাণ করে না” শিরোনামে তিন বাক্য।</p><h3>প্রজেক্ট: softmax মেসেজ classifier (সিন্থেটিক ডেটা)</h3><div class="wgba-playground-slot" data-exercise="ex-les-04-08-project-message-classifier-1"><pre class="wgba-code"><code>// seed-যুক্ত ছদ্ম-দৈব সংখ্যা (mulberry32): একই seed = একই ক্রম
function makeRng(seed) {
  let a = seed &gt;&gt;&gt; 0;
  return function () {
    a = (a + 0x6D2B79F5) &gt;&gt;&gt; 0;
    let t = a;
    t = Math.imul(t ^ (t &gt;&gt;&gt; 15), t | 1);
    t ^= t + Math.imul(t ^ (t &gt;&gt;&gt; 7), t | 61);
    return ((t ^ (t &gt;&gt;&gt; 14)) &gt;&gt;&gt; 0) / 4294967296;
  };
}

// ---- সিন্থেটিক লেবেল-করা ডেটা (আমাদের লেখা—বাস্তব গ্রাহকের নয়) ----
const RAW = {
  shipping: [&quot;ডেলিভারি চার্জ কত&quot;, &quot;ঢাকার বাইরে ডেলিভারি কত দিন লাগে&quot;, &quot;শিপিং খরচ কত&quot;, &quot;চট্টগ্রামে ডেলিভারি দেন&quot;, &quot;ডেলিভারি কি ফ্রি&quot;, &quot;কত দিনে পৌঁছায় পার্সেল&quot;, &quot;শিপিং চার্জ জানতে চাই&quot;, &quot;সিলেটে পাঠাতে খরচ কত&quot;, &quot;ডেলিভারি সময় কত&quot;, &quot;কুরিয়ার চার্জ কত&quot;, &quot;বাইরে পাঠাতে কত দিন&quot;, &quot;ফ্রি ডেলিভারি আছে&quot;],
  returns: [&quot;পণ্য ফেরত দিতে চাই&quot;, &quot;ভাঙা পণ্য এসেছে ফেরত হবে&quot;, &quot;রিটার্ন নীতি কী&quot;, &quot;সাইজ বদল করা যাবে&quot;, &quot;ফেরত দিলে টাকা কবে পাব&quot;, &quot;ভুল রং এসেছে বদলাতে চাই&quot;, &quot;রিটার্ন কীভাবে করব&quot;, &quot;পণ্য পছন্দ হয়নি ফেরত&quot;, &quot;ফেরতের সময়সীমা কত দিন&quot;, &quot;নষ্ট পণ্য বদল চাই&quot;, &quot;টাকা ফেরত চাই&quot;, &quot;এক্সচেঞ্জ করা যাবে&quot;],
  status: [&quot;আমার অর্ডার কোথায়&quot;, &quot;অর্ডার স্ট্যাটাস জানতে চাই&quot;, &quot;পার্সেল কোথায় আছে&quot;, &quot;অর্ডার কি পাঠানো হয়েছে&quot;, &quot;আমার পণ্য এখনও আসেনি&quot;, &quot;ট্র্যাকিং নম্বর দিন&quot;, &quot;অর্ডার কনফার্ম হয়েছে কি&quot;, &quot;কবে পাঠাবেন আমার অর্ডার&quot;, &quot;অর্ডার আপডেট দিন&quot;, &quot;পার্সেল ট্র্যাক করতে চাই&quot;, &quot;আমার অর্ডার এখন কোন অবস্থায়&quot;, &quot;পণ্য পাঠিয়েছেন কি&quot;],
};
const LABELS = Object.keys(RAW);
const tokenize = (s) =&gt; s.toLowerCase().replace(/[?!,।.]/g, &quot; &quot;).split(/\\s+/).filter(Boolean);

// ডুপ্লিকেট-মুক্ত করে seed-যুক্ত ভাগ (প্রতি বিভাগে 9 train, 3 test)
const rand = makeRng(2024);
const train = [], test = [];
for (const label of LABELS) {
  const uniq = [...new Set(RAW[label].map((s) =&gt; tokenize(s).join(&quot; &quot;)))];
  const a = uniq.slice();
  for (let i = a.length - 1; i &gt; 0; i--) { const j = Math.floor(rand() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  a.forEach((text, i) =&gt; (i &lt; 9 ? train : test).push({ text, y: LABELS.indexOf(label) }));
}

// ---- শব্দভাণ্ডার শুধু train থেকে (leakage এড়াতে) ----
const vocab = [...new Set(train.flatMap((d) =&gt; tokenize(d.text)))];
const index = Object.fromEntries(vocab.map((w, i) =&gt; [w, i]));
const featurize = (text) =&gt; { const x = new Array(vocab.length).fill(0); for (const t of tokenize(text)) if (t in index) x[index[t]] += 1; return x; };

// ---- softmax regression ----
const K = LABELS.length, V = vocab.length;
let W = Array.from({ length: K }, () =&gt; new Array(V).fill(0));
let B = new Array(K).fill(0);
function softmax(z) { const m = Math.max(...z); const e = z.map((v) =&gt; Math.exp(v - m)); const s = e.reduce((a, b) =&gt; a + b, 0); return e.map((v) =&gt; v / s); }
const scores = (x) =&gt; W.map((w, k) =&gt; w.reduce((s, wi, i) =&gt; s + wi * x[i], 0) + B[k]);
const predict = (text) =&gt; softmax(scores(featurize(text)));

const lr = 0.5, lambda = 0.001;
const Xtr = train.map((d) =&gt; featurize(d.text));
for (let epoch = 0; epoch &lt; 300; epoch++) {
  const gW = Array.from({ length: K }, () =&gt; new Array(V).fill(0)), gB = new Array(K).fill(0);
  train.forEach((d, n) =&gt; {
    const p = softmax(scores(Xtr[n]));
    for (let k = 0; k &lt; K; k++) {
      const dz = p[k] - (k === d.y ? 1 : 0);
      gB[k] += dz / train.length;
      for (let i = 0; i &lt; V; i++) if (Xtr[n][i]) gW[k][i] += dz * Xtr[n][i] / train.length;
    }
  });
  W = W.map((w, k) =&gt; w.map((wi, i) =&gt; wi - lr * (gW[k][i] + 2 * lambda * wi)));
  B = B.map((b, k) =&gt; b - lr * gB[k]);
}

// ---- মূল্যায়ন: held-out test ----
const argmax = (a) =&gt; a.indexOf(Math.max(...a));
const r2 = (x) =&gt; (x === null ? &quot;—&quot; : Math.round(x * 100) / 100);
const preds = test.map((d) =&gt; argmax(predict(d.text)));
const accTest = preds.filter((p, i) =&gt; p === test[i].y).length / test.length;
const accTrain = train.filter((d) =&gt; argmax(predict(d.text)) === d.y).length / train.length;
console.log(&quot;শব্দভাণ্ডার:&quot;, V, &quot;| train acc:&quot;, r2(accTrain), &quot;| test acc:&quot;, r2(accTest), &quot;(test n=&quot; + test.length + &quot;)&quot;);
LABELS.forEach((lab, k) =&gt; {
  const tp = preds.filter((p, i) =&gt; p === k &amp;&amp; test[i].y === k).length;
  const pp = preds.filter((p) =&gt; p === k).length;
  const ap = test.filter((d) =&gt; d.y === k).length;
